// Attempt via Asgaros REST API (if available)
$asgaros_endpoint = home_url( '/wp-json/asgaros-forum/v1/topic' );
$response = wp_remote_post( $asgaros_endpoint, [
    'headers' => [
        'Content-Type' => 'application/json',
        'Authorization' => 'Basic ' . base64_encode( getenv( 'WP_USER' ) . ':' . getenv( 'WP_APP_PASSWORD' ) ),
