    ] ),
    'timeout' => 15,
] );

if ( ! is_wp_error( $response ) && wp_remote_retrieve_response_code( $response ) === 201 ) {
    $body = json_decode( wp_remote_retrieve_body( $response ), true );
    echo 'Forum topic created via Asgaros REST API. ID: ' . $body['id'] . "\n";
} else {
    // Fallback: create as a standard WordPress post (manually categorize in forum later)
